-- Matriz central de reglas de configuradores para DEV2.
-- La matriz es editable desde Administración y el frontend solo la consume.
INSERT INTO catalog_rules (id, tenant_id, product_type, technical_model, rule_key, rule_value, description, active, updated_at)
SELECT gen_random_uuid(), '00000000-0000-0000-0000-000000000000'::uuid, matrix.product_type, 'TEMPLATE_MATRIX', 'TEMPLATE_MATRIX', matrix.rule_value::jsonb, matrix.description, TRUE, CURRENT_TIMESTAMP
FROM (VALUES
('PUERTA_PEATONAL', '{"requiredFields":["hingeSide","heightMm","widthMm","groundClearanceOption"],"positiveFields":["heightMm","widthMm","clearOpeningWidthMm","clearOpeningHeightMm","freePassageWidthMm","freePassageHeightMm"],"enumFields":{"hingeSide":["LEFT","RIGHT"],"groundClearanceOption":["1","2","3","4","5","OTHER"]},"customClearance":{"optionField":"groundClearanceOption","valueField":"groundClearanceMm","otherValue":"OTHER"},"includedComponents":["Apertura hacia el interior","Tirador exterior 30 mm x 550 mm","Manilla interior inox","Cerradura con pestillo y paletón con una vuelta de llave"],"messages":{"hingeSide":"Seleccione la bisagra izquierda o derecha.","groundClearanceOption":"Seleccione una holgura con el suelo."}}', 'Puerta peatonal: bisagra, medidas, holgura y componentes de serie.'),
('ABATIBLE_UNA', '{"requiredFields":["hingeSide","heightMm","widthMm","groundClearanceOption"],"positiveFields":["heightMm","widthMm"],"enumFields":{"hingeSide":["LEFT","RIGHT"],"groundClearanceOption":["1","2","3","4","5","OTHER"],"motorIncluded":[true,false]},"customClearance":{"optionField":"groundClearanceOption","valueField":"groundClearanceMm","otherValue":"OTHER"},"fixedValues":{"useMode":"PREPARED"},"notes":["Preparada para automatizar","No mostrar manillas ni cerraduras manuales hasta decisión ALUON"],"messages":{"hingeSide":"Seleccione la bisagra izquierda o derecha.","groundClearanceOption":"Seleccione una holgura con el suelo."}}', 'Abatible de una hoja: automatización, bisagra, medidas y holgura.'),
('ABATIBLE_DOS', '{"requiredFields":["activeLeaf","heightMm","widthMm","groundClearanceOption"],"positiveFields":["heightMm","widthMm"],"enumFields":{"activeLeaf":["LEFT","RIGHT"],"groundClearanceOption":["1","2","3","4","5","OTHER"]},"customClearance":{"optionField":"groundClearanceOption","valueField":"groundClearanceMm","otherValue":"OTHER"},"fixedValues":{"useMode":"PREPARED"},"notes":["El reparto entre hoja activa y pasiva queda pendiente de confirmación ALUON"],"messages":{"activeLeaf":"Seleccione una única primera hoja de apertura.","groundClearanceOption":"Seleccione una holgura con el suelo."}}', 'Abatible de dos hojas: primera hoja, automatización, medidas y holgura.'),
('CORREDERA', '{"requiredFields":["openingSide","railType","mountingType","guideSystem","heightMm","widthMm"],"positiveFields":["heightMm","widthMm","sideCollectionMm","mountingDistanceMm"],"enumFields":{"openingSide":["LEFT","RIGHT"],"railType":["CARRIL_16","CARRIL_20"],"mountingType":["A","B"],"guideSystem":["INTERIOR_ROLLERS_U","BRIDGE_ROLLERS"],"motorIncluded":[true,false]},"guideDistances":{"INTERIOR_ROLLERS_U":{"field":"mountingDistanceMm","min":55,"message":"La distancia mínima para rodillos interiores y carril en U es 5,5 cm."},"BRIDGE_ROLLERS":{"field":"mountingDistanceMm","min":80,"message":"La distancia mínima para puente y rodillos es 8 cm."}},"requiredSketchField":"selectedSketch","manufacturingDimensions":[250],"messages":{"openingSide":"Seleccione el sentido de apertura.","railType":"Seleccione un único carril Ø16 mm o Ø20 mm.","mountingType":"Seleccione un único montaje A o B.","guideSystem":"Seleccione un sistema de guía."}}', 'Corredera: apertura, carril, montaje, guía, rodillos y distancias mínimas.'),
('VALLA', '{"requiredFields":["model","color","finish"],"positiveFields":[],"maxSections":8,"minSections":1,"sectionFields":["widthMm","heightMm"],"parametricFields":["verticalDimensionLabel"],"messages":{"sections":"La valla debe tener entre 1 y 8 tramos.","sectionMeasures":"Cada tramo debe tener anchura y altura positivas."}}', 'Vallas: datos de catálogo y hasta ocho tramos con medidas independientes.')
) AS matrix(product_type, rule_value, description)
WHERE NOT EXISTS (
    SELECT 1 FROM catalog_rules existing
    WHERE existing.tenant_id = '00000000-0000-0000-0000-000000000000'::uuid
      AND existing.product_type = matrix.product_type
      AND existing.rule_key = 'TEMPLATE_MATRIX'
      AND existing.technical_model = 'TEMPLATE_MATRIX'
);
